const D = { scale:1, density:.5, energy:.5, hue:210, speed:1, fog:.6, x:.5, y:.6, style:'sumi', pal:'ink', act:'voyage', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style, blueprint=style==='blueprint', neon=style==='neon';
const dens=clp(P.density,0,1), en=clp(P.energy,0,1)*(.5+.5*K.intensity);

// palette: paper + ink tone
const PALS={ink:[42,10,92,210,20], indigo:[224,24,26,214,55], sepia:[34,26,88,28,60], jade:[70,14,90,150,45]};
const pal=PALS[P.pal]||PALS.ink;
let paperH=pal[0],paperS=pal[1],paperB=pal[2], inkH=md(pal[3]+(P.hue-210),360), inkBias=pal[4];
if(blueprint){paperH=214;paperS=70;paperB=30;inkH=200;}
if(neon){paperH=270;paperS=45;paperB=16;inkH=md(P.hue,360);}
const darkPaper=paperB<40;

// number of mountain ridges
const NR=Math.max(3, Math.round(3+dens*5));

// build cached ridge buffer, keyed on size/seed/style/densBucket/pal
const dB=Math.round(dens*4);
const key=W+'x'+Hh+'|'+P.seed+'|'+style+'|'+P.pal+'|'+dB+'|'+NR;
if(S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.clear(); g.noStroke();
  // paper tone underlaid so buffer is opaque (world owns bg)
  g.fill(paperH,paperS,paperB); g.rect(0,0,W,Hh);
  // soft paper mottle
  g.noStroke();
  for(let i=0;i<60;i++){const x=fr(i*1.3)*W,y=fr(i*2.7)*Hh; g.fill(paperH,paperS+6,paperB+(fr(i)*8-4),6); g.circle(x,y,u*(0.05+0.15*fr(i*3)));}
  // ridges back(light)->front(dark): tonal wash + dry-brush crest
  for(let r=0;r<NR;r++){
    const dep=r/(NR-1);               // 0 far .. 1 near
    const baseY=Hh*(0.30+0.52*dep);
    const amp=u*(0.06+0.10*fr(r*7+1))*(0.5+0.8*dep);
    const wl=0.8+fr(r*4+2)*1.8, ph=fr(r*5)*TAU;
    const tone= blueprint? 0 : clp(6+68*dep,6,86);   // darker toward front
    const bri = darkPaper? (blueprint?0: (neon? 100: 96-70*dep)) : (96-78*dep);
    const sat = blueprint? 6 : (neon? 70 : inkBias*(0.5+0.6*dep));
    const yof=(x)=> baseY - amp*Math.sin(x/W*TAU*wl+ph) - amp*0.45*Math.sin(x/W*TAU*wl*2.7+ph*1.7) - amp*0.2*fr(Math.floor(x/9)+r*31);
    // tonal wash fill (the mountain mass)
    g.noStroke();
    if(neon){ g.stroke(inkH,sat,bri,90); g.strokeWeight(1.4+2*dep); g.noFill(); }
    else { g.fill(inkH,sat,bri,blueprint?0:(66+24*dep)); }
    if(!neon){
      g.beginShape(); g.vertex(0,Hh);
      for(let x=0;x<=W;x+=6) g.vertex(x, yof(x));
      g.vertex(W,Hh); g.endShape(g.CLOSE);
    } else {
      g.beginShape();
      for(let x=0;x<=W;x+=6) g.vertex(x, yof(x));
      g.endShape();
    }
    // dry-brush / linework crest
    if(blueprint){ g.stroke(200,10,98,80); g.strokeWeight(1.0+dep); g.noFill();
      g.beginShape(); for(let x=0;x<=W;x+=6) g.vertex(x,yof(x)); g.endShape(); }
    else if(!neon){
      g.noFill(); g.stroke(inkH,sat+10,Math.max(4,bri-30),70); g.strokeWeight(1.0+2.4*dep);
      let prevBreak=0;
      g.beginShape();
      for(let x=0;x<=W;x+=6){ const br=fr(Math.floor(x/7)+r*13); if(br<0.12*(1-dens*0.5)){ g.endShape(); g.beginShape(); } g.vertex(x, yof(x)+ (fr(x+r)*2-1)*1.2 ); }
      g.endShape();
      // dry-brush stipple on the mass
      const nd=Math.floor(u*0.5*dens*(0.3+dep));
      g.noStroke(); g.fill(inkH,sat,Math.max(4,bri-24),22);
      for(let i=0;i<nd;i++){const x=fr(i*1.7+r*99)*W; const yy=yof(x)+fr(i*3+r)*amp*1.4; if(yy<Hh) g.circle(x,yy,u*0.006*(0.5+fr(i)));}
    }
  }
  S.ridge=g;
  S.ridgeInfo={NR};
  // seal stamp sprite (vermilion) baked once
  const ss=Math.ceil(u*0.06); const seal=createGraphics(ss,ss); seal.colorMode(seal.HSB,360,100,100,100); seal.clear();
  seal.noFill(); seal.stroke(8,85,88,92); seal.strokeWeight(ss*0.09); seal.rect(ss*0.12,ss*0.12,ss*0.76,ss*0.76);
  seal.strokeWeight(ss*0.06);
  for(let i=0;i<3;i++){seal.line(ss*0.28,ss*(0.3+i*0.2),ss*0.72,ss*(0.3+i*0.2));}
  seal.line(ss*0.5,ss*0.28,ss*0.5,ss*0.72);
  S.seal=seal; S.ss=ss;
}

// ---- LIVE ----
noStroke();
// base paper (in case buffer offset leaves edge)
background(paperH,paperS,paperB);
image(S.ridge,0,0);

const oldOp=drawingContext.globalCompositeOperation;

// drifting fog bands between ridges (real-time, never re-phasing)
const fogN=Math.floor(3+4*clp(P.fog,0,1));
const fogCol= darkPaper? [paperH,10,paperB+30] : [paperH,4,98];
blendMode(darkPaper?SCREEN:BLEND);
for(let i=0;i<fogN;i++){
  const fy=Hh*(0.32+0.44*fr(i*3.1+2));
  const drift=md(K.t*(6+i*3)*(0.4+0.6*P.speed) + fr(i*7)*W, W+u)-u*0.5;
  const bob=u*0.02*Math.sin(K.t*0.3+i*1.3);
  const a=(darkPaper?12:26)*clp(P.fog,0,1)*(0.6+0.5*Math.sin(K.t*0.2+i));
  fill(fogCol[0],fogCol[1],fogCol[2], clp(a,3,40));
  ellipse(drift, fy+bob, u*(0.5+0.3*fr(i*5)), u*(0.05+0.05*fr(i*9)));
}
blendMode(BLEND);

// tiny boat crossing over minutes (act arc)
let boatT;
if(P.act==='moor'){ boatT=0.5+0.06*Math.sin(K.t*0.05); }
else if(P.act==='storm'){ boatT=frc(K.t*0.02); }
else { boatT=frc(K.t*0.008 + P.seed*0.13); } // voyage: slow drift across in ~2min
const bx=W*(0.06+0.88*boatT), by=Hh*(0.80)+u*0.012*Math.sin(K.t*0.8);
push(); translate(bx,by);
const bs=u*0.05*P.scale*(0.8+0.4*clp(P.energy,0,1));
stroke(inkH, blueprint?8:40, blueprint?98:14, 88); strokeWeight(Math.max(1,bs*0.06)); noFill();
beginShape(); vertex(-bs,0); bezierVertex(-bs*0.7,bs*0.5,bs*0.7,bs*0.5,bs,0); endShape();
line(0,0,0,-bs*0.7); // mast
fill(inkH, blueprint?8:40, blueprint?98:22, 70); noStroke();
triangle(0,-bs*0.66, 0,-bs*0.1, bs*0.6,-bs*0.2); // sail
// wake ripple
stroke(inkH,20,darkPaper?70:30,40); strokeWeight(1); noFill();
for(let i=1;i<=2;i++){arc(-bs*i*1.4, bs*0.2, bs*i*1.6, bs*0.5, 0.15*Math.PI, 0.85*Math.PI);}
pop();

// storm act: raking rain streaks (real-time)
if(P.act==='storm'){
  stroke(inkH,10,darkPaper?80:20, 30+20*en); strokeWeight(1);
  const rn=Math.floor(40*dens+20), sk=u*0.10*(0.6+en);
  for(let i=0;i<rn;i++){const rx=md(fr(i*2.3)*W - K.t*u*0.5, W+u)-u*0.5; const ry=md(fr(i*5.1)*Hh + K.t*u*0.9, Hh+u)-u*0.5; line(rx,ry,rx-sk*0.3,ry+sk);}
}

// low moon / sun disc that breathes (adds continuous soft motion)
const mR=u*0.09*P.scale*(0.9+0.12*K.swell+0.2*A.rms);
noStroke(); blendMode(darkPaper?SCREEN:BLEND);
fill(neon?inkH:(darkPaper?paperH:8), neon?60:(darkPaper?8:70), darkPaper?90:(neon?100:88), darkPaper?26:20);
circle(W*(P.x*0.4+0.5), Hh*(0.22)+u*0.01*Math.sin(K.t*0.3), mR*2);
blendMode(BLEND);

// vermilion seal stamp (lower-right), gentle presence pulse
const sealX=W*(P.x*0.2+0.80), sealY=Hh*0.86;
push(); translate(sealX,sealY); const sp=1+0.04*K.swell; image(S.seal,-S.ss*sp/2,-S.ss*sp/2,S.ss*sp,S.ss*sp); pop();

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.shadowBlur=0; noStroke();
